-- Skill Issue Society schema. The worker also applies this automatically (see src/schema.js).
CREATE TABLE IF NOT EXISTS meta (k TEXT PRIMARY KEY, v TEXT);
CREATE TABLE IF NOT EXISTS players (id TEXT PRIMARY KEY, name TEXT NOT NULL, av TEXT NOT NULL DEFAULT '{}', pin_hash TEXT, adj INTEGER NOT NULL DEFAULT 0, active INTEGER NOT NULL DEFAULT 1, joined_at INTEGER);
CREATE TABLE IF NOT EXISTS sessions (token TEXT PRIMARY KEY, player_id TEXT NOT NULL, is_admin INTEGER NOT NULL DEFAULT 0, admin_until INTEGER, at INTEGER);
CREATE TABLE IF NOT EXISTS matches (id TEXT PRIMARY KEY, data TEXT NOT NULL, status TEXT NOT NULL, voided INTEGER NOT NULL DEFAULT 0, created_at INTEGER);
CREATE TABLE IF NOT EXISTS comments (id INTEGER PRIMARY KEY AUTOINCREMENT, match_id TEXT NOT NULL, who TEXT NOT NULL, text TEXT NOT NULL, at INTEGER);
CREATE TABLE IF NOT EXISTS audit (id INTEGER PRIMARY KEY AUTOINCREMENT, who TEXT, what TEXT, at INTEGER);
CREATE TABLE IF NOT EXISTS docs (k TEXT PRIMARY KEY, v TEXT, updated_at INTEGER);
CREATE TABLE IF NOT EXISTS games (id TEXT PRIMARY KEY, data TEXT NOT NULL, added_by TEXT, at INTEGER);
